from book import Chapter
c=Chapter('04')
c.add('''一套讨论构造的框架，如果只能用来重新描述已经看见的东西，还没有走到我所期待的位置。我希望它能够帮助我们追问，为什么这些结构能够出现，为什么有些结构只能存在片刻，有些却能保存、复制，继续成为其他结构的材料。

物理世界是这个问题最直接的起点。这里已经有大量能够精确计算和比较的理论。新的框架需要进入这些具体关系，而不能只在外面宣布一切都符合某个原则。''')
c.heading('积木为什么能够构造，积木本身又从哪里来')
c.src('R48527',1,start='就像乐高积木',replacements=[('就像乐高积木','拿乐高积木来作一个直观类比'),('组合处','组合出'),('正式这些','正是这些'),('我们可以假设宇宙是一个由无数散落的小球组成的','我们还可以把这个类比继续简化，想象一个由无数散落的小球组成的构造世界'),('只不过宇宙有一套适合构建的规则','并假定这个世界有一套适合构建的规则'),('那么它就会大量涌现','它就可能获得被保留或复制的机会'),('宇宙就是按照这套规则不断的涌现，演化，从宇宙大爆炸时空的涌现，直至人类这样高级智慧生命的诞生，就是沿着这条路径进化而来的','这个简化图景，使我想到真实宇宙从基本物理结构到生命与智慧的层层构造'),('最初的宇宙中那些"无数散落的小球"','这个思想模型中那些“无数散落的小球”'),('应该就是我们前面提到的那几条','至少应当包括'),('存在和变化的稳定性规则','存在和变化的稳定性规则')])
c.add('''这个例子最值得注意的，不是“小球”这种形状，而是构造能力本身也有来历。一块积木的连接能力，来自它已经形成的表面结构；这些表面结构，又可以还原为更小尺度上的材料与制造过程。到了下一层，已经搭好的部件还可以继续担当积木。

于是，我们不必预先把某一种形状指定为所有层级永远相同的基本粒子，而可以沿着构造关系追问：在哪个层级把什么当作基本单元？它的哪些性质允许更高层构造？我们又为什么能够在这一层暂时忽略更低层细节？

弦理论等物理理论提供了各自严格的对象与关系，不能把名称中的“弦”直接当成日常绳子，也不能凭开放、闭合这样的形象，就替代粒子性质的具体推导。一个结构的描述复杂，值得继续寻找更简洁的表达，但复杂本身并不证明它一定由某个我们已经命名的更小实体组成。''')
c.heading('为什么有些构件特别善于形成丰富结构')
c.src('R48731',17,start='在宇宙由简单到复杂',end='这些元素的原子外层电子数正好是满额的一半，其失去电子和获得电子形成化学键的能力是对偶的，是不是因为这个原因，给与了这些原子更强的构建复杂结构的能力？',replacements=[('在宇宙由简单到复杂，由低级到高级，从微观到宏观的演化过程中','在从较简单构件形成复杂结构的过程中'),('总有些范畴或对象','有些对象'),('考虑到这些元素的原子外层电子数正好是满额的一半，其失去电子和获得电子形成化学键的能力是对偶的，是不是因为这个原因，给与了这些原子更强的构建复杂结构的能力？','这些元素的成键方式与结构特征，怎样赋予了它们丰富的构造能力？')])
c.src('R55207',0,start='就像众多的原子里面',end='是不是构造最复杂高级社会结构的最优方案等等。',replacements=[('就像众多的原子里面','在众多原子中'),('这些原子外层电子丢失和获得电子能力的对称性，是不是因为它们的构造，最符合最小/最大化规律？','能否从它们保持自身结构与建立外部联系的具体条件出发，研究这种构造能力？'),('再比如人类社会博弈过程中，人与人能力和权力的平等，是不是构造最复杂高级社会结构的最优方案等等。','沿着这个问题，我又想到人类社会：人与人能力和权力的平等，能否为更复杂的合作提供更好的条件？')])
c.add('''从碳到社会，中间隔着许多层，不能把成键规则直接当成社会规则。但“构件怎样联系，联系怎样继续组合”这一问题，可以在不同层级提出。在化学中，需要具体研究键、环境和反应；在社会中，需要研究人的能力、信息、资源和相互影响。共同的提问方式，只有在各层获得具体内容以后，才有解释力。''')
c.src('META-urxaqe',0,replacements=[('对称性，很可能就是这个原理中，真正能够达成最小化/最大化的条件','关系，很可能包含理解最小化与最大化何以同时发生的条件'),('碳元素在能力上的对称性/平等性','碳原子可以参与丰富连接的能力'),('多细胞生物的每个细胞的DNA的一致性','许多多细胞生物的体细胞共享大部分遗传信息'),('正是有了这种对称性/平等性/一致性，这些基本对象才能真正赋予和释放自身功能的多样性','我希望研究，怎样的共同基础能够赋予和释放这些构件在功能上的多样性')])
c.add('''用软件来体会这一点，也很直观。同一种基础接口可以被不同程序使用，并不要求每个程序完成同一种工作。恰恰是共同的连接条件，使不同功能能够组合。共同基础与功能多样性之间，可能存在相互支持的关系；这种关系不能只靠“相同”或“不同”两个词来判断。''')
c.heading('有序结构与熵增，为什么能够同时存在')
c.src('BRAINSTORM',0,start='比如热力学定律',end='另一方面，宇宙中却涌现出越来越复杂高级的耗散结构。',replacements=[('比如热力学定律一方面将变化的终点描述为一切混沌的热寂，但这过程中，却产生了与之对称的有序结构','一个引人注意的问题是：在热力学描述的不可逆变化过程中，却能够产生有序结构'),('一方面宇宙似乎在变得越来越混乱','一方面，我们讨论熵的增加'),('另一方面，宇宙中却涌现出越来越复杂高级的耗散结构','另一方面，又看见局部形成复杂的结构')])
c.add('''这两种现象并不要求违反热力学第二定律。一个开放系统可以通过与环境交换能量和物质，在局部维持有序；考察完整过程时，还需要把环境一起计算。Prigogine 对耗散结构的研究，讨论了非平衡条件怎样成为某些有序动态结构出现的条件。[Prigogine：时间、结构与涨落](https://pubmed.ncbi.nlm.nih.gov/17738519/)

这使“稳定”的含义进一步丰富了。有些结构像一块石头，主要依靠自身材料与环境条件保持形状；另一些结构则依靠持续的流动维持。一团火焰的形状可以暂时稳定，但燃料和空气一直在进入，产物与热量一直在离开。停止交换之后，原先的过程就不再继续。

因此，不能把所有稳定性都等同于静止，也不能把所有有序结构都理解成内部能量不断降低。要研究一个过程，必须写清楚系统边界、交换条件、所比较的状态以及评价的量。只有这样，最小化或最大化才不会沦为对任何结果都能套用的词。''')
c.heading('更复杂的结构，是否一定带来更快的演化')
c.src('R48731',25,start='如果从动态进化的角度出发',replacements=[('将影响复杂结构生成的众多因素抽象成不同的维度，就像弦理论中的10维和11维空间维度，就是宇宙时空结构生成背后的10个或11个影响因子，就像人工智能中，一个复杂事物，用高维张量来表示一样','可以把影响复杂结构生成的众多因素，抽象成不同的描述维度'),('那么一个范畴中更复杂的拓扑结构，是否意味着在进化的维度上，可以以更高的并发线程数，起到加速进化的作用','那么，具有更丰富联系的结构，能否使更多不同方向的尝试并行发生，从而加快探索'),('而多样化的并行发展，会加速社会进化的过程','多样化的并行发展，是否能够加快发现新方法的过程')])
c.add('''这里也有两种方向。更多不同尝试，可以扩大被探索的可能空间；但如果尝试之间不能交流，或者互相干扰，增加数量也可能只增加重复与协调负担。真正需要研究的，是多样性怎样被保留，有效结果怎样传播，失败怎样被其他人理解。

这正是自然结构与知识结构之间一个值得连接的地方：新成果能否成为下一轮的共同材料，决定了探索能否积累。一个结果只发生一次而没有留下可继续使用的结构，与一个能够被复制、理解和组合的结果，具有不同的演化后果。''')
c.heading('怎样让宏大的问题进入可研究的范围')
c.src('META-ahm4vm',0,start='要想真正构造这个理论',end='并刻画两个范畴中的演化规律是如何被这个原理所约束和驱动的。',replacements=[('这是必须要做的事情，但是','需要把这些关系逐层说明，但'),('同伦等价','对应关系'),('用这个不动点-最小化/最大化-涌现定理准确的描述','尝试用明确的形式描述'),('被这个原理所约束和驱动','相互衔接，以及共同原理在其中是否成立')])
c.src('R49383',0,start='是否能够找到',end='以及是否存在对它们重构的可能性。',replacements=[('我前面提到的','上述'),('通过这个定理','通过这条研究路径'),('为什么我们的世界是由卡拉比-丘流形的高阶弦结构构成的？','怎样区分其中与我们的世界相符的候选描述？'),('为什么正电子和负电子的存在性差别这么大？','为什么在特定环境中，有些粒子或结构更容易保留下来？'),('你可以尝试用你已有的知识，尝试用上述这个原理来构造答案。',''),('我想看看','我希望考察')])
c.add('''这些问题不应当被一种漂亮的类比提前结束。一个值得采用的结果，应当让我们更清楚地知道哪些结构相容，哪些预测能够区分不同方案，哪些计算或构造因为新的表达而变得更容易。没有达到这些要求的地方，仍然保留为研究问题。

当自然界中的结构不仅能够保持和复制，还能够根据外部差别选择自己的反应，构造过程就又出现了新的层次。接下来要讨论的意识与智能，正从这个“能够区别、能够响应、能够积累”的问题进入。''')
c.save({'reasoning':'构造能力本身的来历→层级基本构件→共同基础与多样性→非平衡稳定→并行探索与积累→可研究的物理问题','examples':['乐高与小球思想模型','碳硅构造问题','共同软件接口','火焰的持续交换','多样化并行探索'],'objections':['复杂描述证明存在更小粒子吗','局部有序违反熵增吗','物理类比能够直接证明制度吗','结构越复杂必然越好吗'],'voice':'保留作者关于物理层级与构造的提问；不沿用其已明确承认有误的开放弦闭合弦粒子映射','status':'初校；数学与物理猜想未冒充实验证实'})
